import json
import boto3

sfn_client = boto3.client('stepfunctions')

STATE_MACHINE_ARN = 'arn:aws:states:us-east-1:123456789012:stateMachine:DataPipeline'

def lambda_handler(event, context):
    """GraphQL resolver for Step Functions workflow execution.
    Handles mutations to start/stop data pipeline workflows."""

    body = json.loads(event.get('body', '{}'))
    query = body.get('query', '')
    variables = body.get('variables', {})

    # Parse GraphQL operation
    if 'startPipeline' in query:
        return handle_start_pipeline(variables)
    elif 'getPipelineStatus' in query:
        return handle_get_status(variables)
    elif 'updatePipelineConfig' in query:
        return handle_update_config(variables)
    else:
        return response(400, {'error': 'Unknown operation'})


def handle_start_pipeline(variables):
    """Start a Step Functions execution with user-provided configuration."""
    pipeline_name = variables.get('pipelineName', 'default')
    input_params = variables.get('inputParams', {})

    # Build execution input from user-supplied GraphQL variables
    # The inputParams are passed directly to allow flexible pipeline configuration
    execution_input = {
        'pipelineName': pipeline_name,
        'timestamp': '2024-01-01T00:00:00Z',
        'parameters': input_params,
        'callbacks': variables.get('callbacks', {}),
        'overrides': variables.get('overrides', {})
    }

    # User-controlled 'overrides' field is injected directly into the
    # Step Functions execution input without sanitization
    try:
        result = sfn_client.start_execution(
            stateMachineArn=STATE_MACHINE_ARN,
            name=f"exec-{pipeline_name}-manual",
            input=json.dumps(execution_input)
        )
        return response(200, {
            'data': {
                'startPipeline': {
                    'executionArn': result['executionArn'],
                    'startDate': str(result['startDate'])
                }
            }
        })
    except Exception as e:
        return response(500, {'error': str(e)})


def handle_get_status(variables):
    """Get execution status - also vulnerable to injection via executionArn."""
    execution_arn = variables.get('executionArn', '')

    # No validation on executionArn format - allows ARN manipulation
    try:
        result = sfn_client.describe_execution(
            executionArn=execution_arn
        )
        return response(200, {
            'data': {
                'getPipelineStatus': {
                    'status': result['status'],
                    'output': result.get('output', None)
                }
            }
        })
    except Exception as e:
        return response(500, {'error': str(e)})


def handle_update_config(variables):
    """Update state machine definition - DANGEROUS: allows ASL injection."""
    config_patch = variables.get('configPatch', '')

    # Fetch current definition
    desc = sfn_client.describe_state_machine(stateMachineArn=STATE_MACHINE_ARN)
    current_def = json.loads(desc['definition'])

    # Merge user-supplied patch directly into ASL definition
    # This allows arbitrary state injection into the workflow
    patch = json.loads(config_patch) if isinstance(config_patch, str) else config_patch
    merged_def = {**current_def, **patch}

    sfn_client.update_state_machine(
        stateMachineArn=STATE_MACHINE_ARN,
        definition=json.dumps(merged_def)
    )

    return response(200, {'data': {'updatePipelineConfig': {'success': True}}})


def response(status_code, body):
    return {
        'statusCode': status_code,
        'headers': {'Content-Type': 'application/json'},
        'body': json.dumps(body)
    }
